ALTER TYPE "GameType" ADD VALUE IF NOT EXISTS 'LETTER_DUEL';
ALTER TYPE "GameStatus" ADD VALUE IF NOT EXISTS 'LOST';
ALTER TYPE "GameStatus" ADD VALUE IF NOT EXISTS 'DRAW';
CREATE TYPE "LetterDuelMode" AS ENUM ('PRIVATE', 'RANDOM');
CREATE TYPE "LetterDuelStatus" AS ENUM ('WAITING', 'ACTIVE', 'ENDED');
CREATE TYPE "LetterDuelRoundStatus" AS ENUM ('PICKING', 'ANSWERING', 'JUDGING', 'RESOLVED', 'CANCELLED');
CREATE TYPE "LetterDuelSubmissionStatus" AS ENUM ('PENDING', 'ACCEPTED', 'REJECTED', 'ERROR');
ALTER TABLE "GameSession" ADD COLUMN "letterDuelRoundId" TEXT, ADD COLUMN "duelOwnScore" INTEGER, ADD COLUMN "duelOpponentScore" INTEGER;
CREATE TABLE "LetterDuelConnection" ("id" TEXT NOT NULL,"mode" "LetterDuelMode" NOT NULL,"status" "LetterDuelStatus" NOT NULL DEFAULT 'WAITING',"inviteToken" TEXT,"playerOneId" TEXT NOT NULL,"playerTwoId" TEXT,"playerOneHeartbeat" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"playerTwoHeartbeat" TIMESTAMP(3),"stateVersion" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),CONSTRAINT "LetterDuelConnection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LetterDuelRound" ("id" TEXT NOT NULL,"connectionId" TEXT NOT NULL,"number" INTEGER NOT NULL,"status" "LetterDuelRoundStatus" NOT NULL DEFAULT 'PICKING',"playerOneLetter" TEXT,"playerTwoLetter" TEXT,"pickDeadline" TIMESTAMP(3) NOT NULL,"answerDeadline" TIMESTAMP(3),"winnerUserId" TEXT,"winningWord" TEXT,"resultReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedAt" TIMESTAMP(3),CONSTRAINT "LetterDuelRound_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LetterDuelSubmission" ("id" TEXT NOT NULL,"roundId" TEXT NOT NULL,"userId" TEXT NOT NULL,"word" TEXT NOT NULL,"status" "LetterDuelSubmissionStatus" NOT NULL DEFAULT 'PENDING',"reason" TEXT,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"judgedAt" TIMESTAMP(3),CONSTRAINT "LetterDuelSubmission_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LetterDuelWordJudgment" ("word" TEXT NOT NULL,"accepted" BOOLEAN NOT NULL,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LetterDuelWordJudgment_pkey" PRIMARY KEY ("word"));
CREATE UNIQUE INDEX "LetterDuelConnection_inviteToken_key" ON "LetterDuelConnection"("inviteToken");
CREATE INDEX "LetterDuelConnection_status_mode_createdAt_idx" ON "LetterDuelConnection"("status", "mode", "createdAt");
CREATE INDEX "LetterDuelConnection_playerOneId_status_idx" ON "LetterDuelConnection"("playerOneId", "status");
CREATE INDEX "LetterDuelConnection_playerTwoId_status_idx" ON "LetterDuelConnection"("playerTwoId", "status");
CREATE UNIQUE INDEX "LetterDuelRound_connectionId_number_key" ON "LetterDuelRound"("connectionId", "number");
CREATE INDEX "LetterDuelRound_connectionId_status_idx" ON "LetterDuelRound"("connectionId", "status");
CREATE INDEX "LetterDuelSubmission_roundId_receivedAt_idx" ON "LetterDuelSubmission"("roundId", "receivedAt");
CREATE UNIQUE INDEX "GameSession_letterDuelRoundId_userId_key" ON "GameSession"("letterDuelRoundId", "userId");
ALTER TABLE "LetterDuelConnection" ADD CONSTRAINT "LetterDuelConnection_playerOneId_fkey" FOREIGN KEY ("playerOneId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LetterDuelConnection" ADD CONSTRAINT "LetterDuelConnection_playerTwoId_fkey" FOREIGN KEY ("playerTwoId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LetterDuelRound" ADD CONSTRAINT "LetterDuelRound_connectionId_fkey" FOREIGN KEY ("connectionId") REFERENCES "LetterDuelConnection"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LetterDuelSubmission" ADD CONSTRAINT "LetterDuelSubmission_roundId_fkey" FOREIGN KEY ("roundId") REFERENCES "LetterDuelRound"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LetterDuelSubmission" ADD CONSTRAINT "LetterDuelSubmission_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "GameSession" ADD CONSTRAINT "GameSession_letterDuelRoundId_fkey" FOREIGN KEY ("letterDuelRoundId") REFERENCES "LetterDuelRound"("id") ON DELETE CASCADE ON UPDATE CASCADE;
